mapper.update:
update `groupon`
current_size = #{currentSize}, status = #{status}, complete_time = #{completeTime}, expire_time = #{expireTime}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select g.* from `groupon` g
inner join groupon_member gm on gm.groupon_id = g.id
where gm.user_id = #{userId}

    and g.status = #{status}

order by g.create_time desc

select
    sum(case when g.status = 1 then 1 else 0 end) as ongoing,
    sum(case when g.status = 2 then 1 else 0 end) as success,
    sum(case when g.status = 3 then 1 else 0 end) as failed,
    sum(case when g.status = 4 then 1 else 0 end) as expired,
    (select count(*)
       from groupon_member m
       join groupon g2 on g2.id = m.groupon_id

           and g2.create_time >= #{begin}
           and g2.create_time <= #{end}
       ) as memberCount,
    (select count(*)
       from orders o
       where o.is_groupon = 1
         and o.order_time >= #{begin}
         and o.order_time <= #{end}
    ) as grouponOrderCount,
    (select ifnull(sum(o.amount), 0)
       from orders o
       where o.is_groupon = 1 and o.pay_status = 1 and o.status in (2,3,4,5)
         and o.order_time >= #{begin}
         and o.order_time <= #{end}
    ) as grouponTurnover
from `groupon` g

    and g.create_time >= #{begin}
    and g.create_time <= #{end}
